package org.marketreview.nativeapp;
import android.content.Context;
import android.widget.*;
import org.json.*;
import java.util.*;
/** main is pure model; run(Context) is an isolated native device UI helper. */
public final class AccountAnalysisChecks {
 static int checks;static void need(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static JSONObject buy()throws Exception{return new JSONObject().put("id","b").put("accountId","a").put("instrumentId","SH:stock:600001").put("date","2026-10-01").put("side","buy").put("quantity",100).put("price",10.).put("fee",5.).put("tax",0.);}
 static void model()throws Exception{JSONObject account=new JSONObject().put("id","a"),buy=buy(),sell=new JSONObject(buy.toString()).put("id","s").put("date","2026-10-02").put("side","sell").put("quantity",40).put("price",12.).put("fee",1.).put("tax",1.);JSONArray trades=new JSONArray().put(buy).put(sell);JSONObject quotes=new JSONObject().put("SH:stock:600001",new JSONObject().put("price",11.).put("tradeDate","2026-10-12")),raw=new JSONObject().put("snapshot_date","2026-10-01").put("cash_balance",1000.).put("total_market_value",2000.).put("total_assets",3000.).put("total_pnl",100.),report=new JSONObject().put("id","h").put("accountId","a").put("legacySource","portfolio_snapshots").put("legacyOriginal",raw);JSONObject p=AccountAnalysis.evaluate(account,trades,quotes,new JSONArray().put(report));need(p.isNull("cashBalance")&&p.isNull("totalAssets"),"missing cash zero");need(p.getDouble("realized")==76&&p.getDouble("unrealized")==57,"average cost pnl");need(p.getDouble("recordedCashFlow")==-527,"old fee/amount cash semantics");account.put("cashBalance",0.);p=AccountAnalysis.evaluate(account,trades,quotes,new JSONArray().put(report));need(p.getDouble("totalAssets")==660,"explicit zero cash");String history=p.getJSONArray("history").toString();quotes.put("SH:stock:600001",new JSONObject().put("price",99.));need(AccountAnalysis.evaluate(account,trades,quotes,new JSONArray().put(report)).getJSONArray("history").toString().equals(history),"future quotes rewriting history");need(p.isNull("performanceReturn"),"invented return");buy.remove("fee");need(AccountAnalysis.evaluate(account,new JSONArray().put(buy),quotes,new JSONArray()).isNull("recordedCashFlow"),"missing fee silently zero");}
 public static int run(Context c)throws Exception{checks=0;model();BusinessStore store=new BusinessStore(c,"account-analysis-check-"+UUID.randomUUID()+".sqlite");try{JSONObject trade=buy();trade.remove("id");trade.put("accountId","local");store.save("trades",trade);store.save("reports",new JSONObject().put("title","原快照").put("text","原记录").put("accountId","local").put("legacySource","portfolio_snapshots").put("legacyOriginal",new JSONObject().put("snapshot_date","2026-10-01").put("cash_balance",1000.).put("total_market_value",2000.).put("total_assets",3000.)));String before=store.backup().toString();AccountAnalysisScreen screen=new AccountAnalysisScreen(c,store,false,()->new JSONArray());need(((TextView)screen.findViewWithTag("analysisSummary")).getText().toString().contains("输入现金 未知"),"cash unknown UI");((Button)screen.findViewWithTag("analysisHistoryMode")).performClick();TextView item=screen.findViewWithTag("analysisSnapshot_0");need(item!=null&&item.getText().toString().contains("3000"),"history original value");item.performClick();need(((TextView)screen.findViewWithTag("analysisOriginal_0")).getVisibility()==android.view.View.VISIBLE,"original selected");((Button)screen.findViewWithTag("analysisFlowMode")).performClick();screen.reload();need(store.read("accounts").toString().equals(new JSONObject(before).getJSONArray("accounts").toString())&&store.read("trades").toString().equals(new JSONObject(before).getJSONArray("trades").toString()),"read-only UI wrote records");JSONObject changed=store.read("accounts").getJSONObject(0);changed.put("type","paper");store.save("accounts",changed);screen.reload();need(((TextView)screen.findViewWithTag("analysisSummary")).getText().length()==0&&screen.findViewWithTag("analysisSnapshot_0")==null,"empty account clears stale results");return checks;}finally{store.close();}}
 public static void main(String[] args)throws Exception{checks=0;model();System.out.println("account analysis pure model: "+checks+" checks GREEN; native device UI helper compiled, not run");}
}
